/* 报警指示灯：PA26（板级唯一分配给用户的 GPIO 输出脚，走标准 GPIO 驱动
 * /dev/gpio1）。**不是 PA32** —— 原理图上 PA32 标着 RGB LED，但这块板子
 * （SF32LB52-DevKit-LCD V1.2.x 实物）上只焊了 GPIO/PWR/CHG 三个灯，PA32
 * 那颗 RGB LED 没有实物，驱动它不会有任何可见效果。
 *
 * PA26 在板级 bringup 里已经 mux 成 GPIO_A26 并由驱动注册成 /dev/gpio1
 * （bsp_pinmux.c / sf32lb52_devkit_lcd.h 的 GPIO_OUT1），所以这里只按标准
 * GPIO 驱动接口开一次 fd 常驻，不再自己动 pinmux。
 *
 * 注意：wiki 上 PA26 还写着"SD 卡 CD / flash2 片选共用"，本工程没把 CD 接进
 * 驱动（SD 卡只走 SPI1 数据线），所以当作用户输出脚使用是安全的；
 * 换板子/换配置前请复核这一条。
 */

#define ALARM_LED_DEV        "/dev/gpio1"

static int g_alarm_led_fd = -1;

static void alarm_led_write(bool on)
{
  bool value;

#if !ALARM_LED_ACTIVE_HIGH
  on = !on;
#endif

  if (g_alarm_led_fd < 0)
    {
      g_alarm_led_fd = open(ALARM_LED_DEV, O_RDWR);
      if (g_alarm_led_fd < 0)
        {
          return;
        }
    }

  value = on;
  if (write(g_alarm_led_fd, &value, 1) != 1)
    {
      /* 驱动不认这个脚/被占用：关掉 fd，下次重试 */
      close(g_alarm_led_fd);
      g_alarm_led_fd = -1;
    }
}

static void alarm_led_init(void)
{
  /* 板级 bringup 已把 PA26 配成输出并注册成 /dev/gpio1；
   * 这里只显式确保一次"输出"方向，失败也不致命（下面 write 会兜底）。 */

  int fd = open(ALARM_LED_DEV, O_RDWR);

  if (fd < 0)
    {
      return;
    }

#if defined(GPIOIOC_SETPINTYPE)
  ioctl(fd, GPIOIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
#elif defined(GPIOIOC_CONFIG)
  ioctl(fd, GPIOIOC_CONFIG, (unsigned long)GPIO_OUTPUT_PIN);
#endif

  close(fd);
  alarm_led_write(false);
}
