 * Name: alarm_emit
 *
 * Description: 在**工作线程**上下文里调用上层注册的回调。
 *
 ****************************************************************************/

static void alarm_emit(enum alarm_event_e event,
                       FAR const struct alarm_status_s *status)
{
  alarm_cb_t cb;
  FAR void  *arg;

  nxmutex_lock(&g_alarm.lock);
  cb  = g_alarm.cb;
  arg = g_alarm.cb_arg;
  nxmutex_unlock(&g_alarm.lock);

  if (cb != NULL)
    {
      cb(event, status, arg);
    }
}

