 *   与默认自检里的 step_buttons() 不同：这里"没按到"是**失败**。
 *   默认自检那一步只证明"节点能读"，所以没人按也算 PASS，等于按键从没
 *   真按过；要验证按键本身必须用本命令，按到才 PASS。
 *
 *   用 poll() 带超时地等，配合 clock_systime_ticks() + TICK2MSEC() 计时
 *   （不自己累加固定值，理由见 step_rtc 的注释）。/dev/buttons 的 read()
 *   返回的是位掩码：0 = 全松开，非 0 = 有键按下。
 *
 ****************************************************************************/

static int step_button_wait(int seconds)
{
  clock_t t0;
  uint32_t elapsed_ms = 0;
  int fd;

  if (seconds < 1)
    {
      seconds = BTN_DEFAULT_WAIT_SEC;
    }

  printf("[BUTTON] %s 等待按下（最多 %d 秒）\n", BTN_DEV, seconds);

  fd = open(BTN_DEV, O_RDONLY | O_NONBLOCK);
  if (fd < 0)
    {
      printf("      open 失败: %d\n", errno);
      report("按键", 0, "open /dev/buttons 失败");
      return -1;
    }

  printf("      请按一下 Key2（PA11）...\n");

  t0 = clock_systime_ticks();

  while (elapsed_ms < (uint32_t)seconds * 1000)
    {
      struct pollfd pfd;
      uint32_t remain_ms = (uint32_t)seconds * 1000 - elapsed_ms;
      uint8_t mask = 0;         /* btn_buttonset_t，按位表示按键集合 */
      ssize_t n;
      int ret;
      int i;

      pfd.fd      = fd;

[结果]       pfd.fd      = fd;
      pfd.events  = POLLIN;
      pfd.revents = 0;

      /* 每次最多等 BTN_POLL_MS：这样能定期用单调时钟刷新 elapsed_ms，
       * 不会因为一次 poll 睡太久而越过截止时间。 */

      ret = poll(&pfd, 1,
                 remain_ms < BTN_POLL_MS ? (int)remain_ms : BTN_POLL_MS);

      if (ret < 0)
        {
          usleep(BTN_POLL_MS * 1000);   /* poll 不可用时退化成定时轮询 */
        }
      else if (ret == 0)
        {
          elapsed_ms = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);
          continue;
        }

      n = read(fd, &mask, sizeof(mask));
      if (n >= (ssize_t)sizeof(mask) && mask != 0)
        {
          char bits[32];
          char detail[64];
          size_t pos = 0;

          /* 打印"哪一位被按下"：位号列表 + 十六进制掩码 */

          bits[0] = '\0';
          for (i = 0; i < 8; i++)
            {
              if ((mask & (1u << i)) == 0)
                {
                  continue;
                }

              pos += (size_t)snprintf(bits + pos, sizeof(bits) - pos,
                                      "%s%d", pos > 0 ? "," : "", i);
            }

          printf("      按下: buttonset=0x%02x  位号=%s%s\n",
                 (unsigned)mask, bits,
                 (mask & 1) != 0 ? "（位 0 = Key2 / PA11，本板唯一按键）" : "");

          snprintf(detail, sizeof(detail), "buttonset=0x%02x 位 %s",
                   (unsigned)mask, bits);
          report("按键", 1, detail);
          close(fd);
          return OK;
        }

      elapsed_ms = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);
    }

  close(fd);

  printf("      等了 %u ms 没检测到按下（buttonset 一直是 0）\n",
         (unsigned)elapsed_ms);
  report("按键", 0, "超时，没检测到按下");
  return -1;

