int mqtt_publish(const char *topic, const char *payload, int qos, bool retain)
{
    if (!mqtt_config.connected) {
        printf("MQTT not connected\n");
        return -1;
    }

    printf("Publish to %s: %s\n", topic, payload);
    int ret = mqtt_send_publish(topic, payload, qos, retain);

    /* send() 失败 = 这条 TCP 连接已经死了（broker 断流/被限流/网络换过）。
     * 但 connected 还是 true，network_task 只在 !connected 时才重连，
     * 于是会一直"假装连着"：报警上报永远发不出去，直到重启板子。
     * 所以这里主动断开，让 network_task 走重连（并会换 broker）。 */
    if (ret < 0) {
        printf("MQTT publish failed: %d, dropping connection for reconnect\n", ret);
        mqtt_disconnect();
    }

    return ret;
}
