int alarm_clear(void)
{
  bool was_active;

  nxmutex_lock(&g_alarm.lock);
  was_active = g_alarm.status.active;

  if (was_active)
    {
      g_alarm.status.active = false;
      g_alarm.exit_event    = ALARM_EVENT_CLEARED;
    }

  nxmutex_unlock(&g_alarm.lock);

  if (was_active)
    {
      nxsem_post(&g_alarm.wake);
    }

  return OK;
}

